<?php declare(strict_types=1);use yii\helpers\Html;$title=$stage==='password'?'Введите пароль':'Вход в FMonitor';$intro=$stage==='password'?'Используйте пароль, который вы задали при первом входе.':'Введите корпоративный email. Доступ открыт пользователям FMonitor.';?>
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=Html::encode($title)?> — FMonitor</title><script src="/pilot/assets/preloader.js"></script><link rel="stylesheet" href="/pilot/assets/shlz.css"><link rel="stylesheet" href="/pilot/assets/pilot.css"><link rel="icon" type="image/svg+xml" href="/pilot/assets/favicon.svg"></head><body class="shlz-scope fm2-auth-page"><main class="fm2-auth-layout"><section class="fm2-auth-brand" aria-label="FMonitor"><img src="/pilot/assets/favicon.svg" alt="" width="56" height="56"><div><strong>FMonitor</strong><span>Управление монтажными работами</span></div></section><section class="fm2-auth-card"><div class="fm2-auth-heading"><span class="fm2-auth-kicker">ЩЛЗ · защищённый контур</span><h1><?=Html::encode($title)?></h1><p><?=Html::encode($intro)?></p></div><form method="post" action="/pilot/login" class="fm2-auth-form"><input type="hidden" name="<?=Html::encode(Yii::$app->request->csrfParam)?>" value="<?=Html::encode(Yii::$app->request->csrfToken)?>"><?php if($stage==='password'):?><input type="hidden" name="email" value="<?=Html::encode($email)?>"><div class="fm2-auth-identity"><span class="fm2-auth-avatar" aria-hidden="true"><?=Html::encode(mb_strtoupper(mb_substr($name,0,1)))?></span><span><strong><?=Html::encode($name)?></strong><small><?=Html::encode($email)?></small></span></div><label class="shlz-field"><span class="shlz-field__label">Пароль</span><span class="shlz-field__control"><input class="shlz-input" type="password" name="password" autocomplete="current-password" maxlength="200" required autofocus></span></label><?php else:?><label class="shlz-field"><span class="shlz-field__label">Корпоративный email</span><span class="shlz-field__control"><input class="shlz-input" type="email" name="email" value="<?=Html::encode($email)?>" placeholder="name@shlz.ru" autocomplete="username" inputmode="email" required autofocus></span></label><?php endif?><?php if($error!==''):?><p class="fm2-auth-error" role="alert"><?=Html::encode($error)?></p><?php endif?><button class="shlz-button shlz-button--primary fm2-auth-submit" type="submit"><?=$stage==='password'?'Войти':'Продолжить'?></button><?php if($stage==='password'):?><a class="fm2-auth-back" href="/pilot/login">Войти с другим email</a><?php endif?></form></section><p class="fm2-auth-note">Пароль хранится только в виде необратимого криптографического хэша.</p></main></body></html>
